import sys, json, time
from pathlib import Path
from dataclasses import asdict
sys.path.insert(0,sys.argv[1])
from bench import PROGRAMS, capture
from examples.riscv.model import build_cpu
for line in sys.stdin:
    request=json.loads(line)
    options={key:request[key] for key in ('latency','cache','reverse')}
    program=PROGRAMS[request['name']]
    if request['op']=='capture':
        response=capture(program,**options)
    else:
        elapsed=[]
        for _ in range(request.get('batch',3)):
            cpu=build_cpu(program,memory_latency=options['latency'],data_words=64,cache=options['cache'],reverse=options['reverse'])
            start=time.perf_counter_ns()
            for tick in range(5000):
                cpu.sim.step()
                if cpu.halted:
                    break
            elapsed.append(time.perf_counter_ns()-start)
            assert cpu.halted
        response={'ns':sum(elapsed)/len(elapsed),'cycles':cpu.sim.tick,'stats':asdict(cpu.sim.stats)}
    print(json.dumps(response),flush=True)

