import gzip,hashlib,json,os,platform,statistics,subprocess,sys
from pathlib import Path
root=Path(__file__).parent
versions=('before','begin','combined')
affinity=None
if hasattr(os,'sched_getaffinity'):
    affinity=min(os.sched_getaffinity(0)); os.sched_setaffinity(0,{affinity})
workers={v:subprocess.Popen([sys.executable,str(root/'worker.py'),str(root/v)],stdin=subprocess.PIPE,stdout=subprocess.PIPE,text=True) for v in versions}
def request(v,case,op,**extra):
    p=workers[v]; p.stdin.write(json.dumps(dict(case,op=op,**extra))+'\n'); p.stdin.flush()
    line=p.stdout.readline()
    if not line: raise RuntimeError(f'{v} exited {p.poll()}')
    return json.loads(line)
traces={v:{} for v in versions}; results={}; repeats=7
try:
    for name in ('alu','sum','control'):
        for latency in (1,3,5):
            for cache in (True,False):
                for reverse in (False,True):
                    case=dict(name=name,latency=latency,cache=cache,reverse=reverse)
                    tag=f'{name}-lat{latency}-cache{int(cache)}-reverse{int(reverse)}'
                    for v in versions: traces[v][tag]=request(v,case,'capture')
                    for v in versions[1:]:
                        assert traces[v][tag]==traces['before'][tag],f'trace mismatch {v} {tag}'
                    samples={v:[] for v in versions}; last={}
                    for v in versions: request(v,case,'time',batch=1)
                    for rep in range(repeats):
                        order=versions[rep%3:]+versions[:rep%3]
                        if rep%2: order=tuple(reversed(order))
                        for v in order:
                            last[v]=request(v,case,'time',batch=3)
                            samples[v].append(last[v]['ns'])
                    for v in versions[1:]:
                        assert last[v]['stats']==last['before']['stats'],f'stats mismatch {v} {tag}'
                    results[tag]={v:dict(samples_ns=samples[v],median_ns=statistics.median(samples[v]),cycles=last[v]['cycles'],stats=last[v]['stats']) for v in versions}
        print('Verified and timed',name,flush=True)
finally:
    for p in workers.values(): p.stdin.close()
    for p in workers.values(): p.wait()
hashes={}
for v,data in traces.items():
    encoded=json.dumps(data,separators=(',',':')).encode()
    with gzip.open(root/f'{v}-traces.json.gz','wb') as f:f.write(encoded)
    hashes[v]=hashlib.sha256(encoded).hexdigest()
ratios={v:statistics.median(row[v]['median_ns']/row['before']['median_ns'] for row in results.values()) for v in versions}
by_program={name:{v:statistics.median(row[v]['median_ns']/row['before']['median_ns'] for tag,row in results.items() if tag.startswith(name+'-')) for v in versions} for name in ('alu','sum','control')}
report=dict(python=platform.python_version(),machine=platform.machine(),affinity_cpu=affinity,scope='36 complete program configurations; 7 interleaved samples, 3 fresh instances per sample; construction/oracle/traces outside timer; sim.step + HALT check timed; counters on; observer off',trace_sha256=hashes,median_ratio=ratios,by_program=by_program,workloads=results)
(root/'timing.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps(dict(median_ratio=ratios,by_program=by_program,trace_sha256=hashes),indent=2))
for name in ('alu','sum','control'):
    row=results[f'{name}-lat5-cache1-reverse0']
    print(name,{v:round(row[v]['median_ns']/1e6,3) for v in versions})
